style.css:
@-moz-document domain("userstyles.org") {
/* Fondo beige general */
  body {
    background-color: #f5f1e8 !important; /* beige claro */
    color: #222 !important;
    font-family: 'Helvetica Neue', Arial, sans-serif !important;
  }

  /* Encabezado limpio con detalles sutiles */
  header, .header, .navbar {
    background-color: #ffffffdd !important;
    border-bottom: 2px solid #f1c40f !important;
    box-shadow: 0 2px 6px rgba(0,0,0,0.1);
  }

  /* Botones estilo taxi neoyorquino */
  button, .button, input[type="submit"] {
    background-color: #f1c40f !important;
    color: #000 !important;
    border: none !important;
    border-radius: 6px !important;
    font-weight: bold;
    transition: all 0.3s ease-in-out;
  }

  button:hover, .button:hover, input[type="submit"]:hover {
    background-color: #e0b800 !important;
    box-shadow: 0 0 5px #f1c40f;
    cursor: pointer;
  }

  /* Enlaces elegantes */
  a {
    color: #1a1a1a !important;
    text-decoration: none;
    border-bottom: 1px dashed #888;
  }

  a:hover {
    color: #f1c40f !important;
    border-bottom: 1px solid #f1c40f;
  }

  /* Áreas de texto y código */
  pre, code, textarea {
    background-color: #fffaf3 !important;
    color: #333 !important;
    border-radius: 4px;
    padding: 10px;
    font-family: monospace;
    border: 1px solid #ddd;
  }

  /* Editor de código */
  #editor, .ace_editor {
    background-color: #fefcf8 !important;
    color: #222 !important;
  }

  /* Títulos refinados */
  h1, h2, h3, h4, h5 {
    color: #000 !important;
    font-family: 'Franklin Gothic Medium', 'Arial Narrow', Arial, sans-serif;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }

  /* Tarjetas y cajas de contenido */
  .panel, .box, .card, .container {
    background-color: #ffffffcc !important;
    border: 1px solid #ccc !important;
    border-radius: 8px;
    padding: 10px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.05);
  }

  footer {
    background-color: #f0eae0 !important;
    color: #666 !important;
    border-top: 1px solid #ccc;
  }
}
